"""TASK-20260929-7fb81e review computation J1 (vi), D-CARRY.

Extract, by ONE script applied identically to the version-2 audit sheet
(bound by TASK-20260929-36a146) and the version-3 audit sheet (bound by
TASK-20260929-76139a): the constants block, the committed m = 4 range (every
place it is written), every design figure of design_figures (the superset of
the Q1 to Q7 quantities the carried J5 compared), and the stage0_code DESIGN
table, literal constants and S0 comparison calls (by AST, never executed).
Diff value by value. Output: the full table (every leaf, both versions,
identical or not) and the list of differences. Coverage by constants_delta is
judged by the validator from the printed differences and recorded in the
report.  Libraries: Python 3.11.15, PyYAML 6.0.1 (pure Python loader).
"""
import ast
import difflib
import hashlib
import json
import os
import sys

import yaml

S = os.path.dirname(os.path.abspath(__file__))
SHEET = {"v2": os.path.join(S, "v2", "audit.yaml"), "v3": os.path.join(S, "v3", "audit.yaml")}
SPEC = {"v2": os.path.join(S, "v2", "spec.yaml"), "v3": os.path.join(S, "v3", "spec.yaml")}
HYP = {"v2": os.path.join(S, "v2", "hyp.yaml"), "v3": os.path.join(S, "v3", "hyp.yaml")}

# Q mapping of design_figures / constants paths (DEC-20260929-1f5fcb
# j5_versus_contract quantity list; plan blind_rederivation.quantity)
QMAP = [
    ("design_figures.column.log2_B_cap", "Q1"),
    ("design_figures.column.log2_T_gen", "Q2"),
    ("design_figures.column.log2_P_gen", "Q2"),
    ("design_figures.column.identity_residual", "Q3"),
    ("design_figures.column.log2_LA", "Q3"),
    ("design_figures.m5_window_at_B_cap", "Q4"),
    ("constants.rho", "Q5"),
    ("design_figures.m4_envelope", "Q6"),
    ("design_figures.m4_sub_cap_slice", "Q6 (slice compared by J5 at per-B row k = 0)"),
    ("design_figures.m4_cap_slice", "Q6 (slice compared by J5 at its B_cap(4) point)"),
    ("design_figures.l1_slices", "Q7"),
    ("constants.comparator_inputs", "Q0/Q4/Q6/Q7 inputs"),
    ("constants.m4_envelope_range", "committed m = 4 range"),
]


def qtag(path):
    for pre, q in QMAP:
        if path.startswith(pre):
            return q
    return "carried figure (not a J5 quantity)"


def flatten(x, pre, out):
    if isinstance(x, dict):
        for k, v in x.items():
            flatten(v, pre + "." + str(k), out)
    elif isinstance(x, list) and x and all(not isinstance(e, (dict, list)) for e in x):
        out[pre] = x
    elif isinstance(x, list):
        for i, v in enumerate(x):
            flatten(v, pre + "[%d]" % i, out)
    else:
        out[pre] = x
    return out


def stage0_ast(src):
    tree = ast.parse(src)
    consts, design = {}, None
    for node in tree.body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name):
            name = node.targets[0].id
            if name == "DESIGN":
                design = ast.literal_eval(node.value)
            else:
                try:
                    consts[name] = ast.literal_eval(node.value)
                except Exception:
                    consts[name] = "<non-literal: %s>" % ast.unparse(node.value)[:60]
    # every chk / chkw call anywhere in the module, unparsed
    calls = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Name) and node.func.id in ("chk", "chkw"):
            calls.append(ast.unparse(node))
    # self-check dict keys and expressions
    selfchecks = {}
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign):
            for t in node.targets:
                if isinstance(t, ast.Subscript) and ast.unparse(t) == "out['self_checks']":
                    if isinstance(node.value, ast.Dict):
                        for k, v in zip(node.value.keys, node.value.values):
                            selfchecks[ast.literal_eval(k)] = ast.unparse(v)
    funcs = {n.name: ast.unparse(n) for n in tree.body if isinstance(n, ast.FunctionDef)}
    return consts, design, sorted(calls), selfchecks, funcs


def jsonable(v):
    if isinstance(v, tuple):
        return list(v)
    return v


def main():
    data = {}
    for v in ("v2", "v3"):
        raw = open(SHEET[v], "rb").read()
        doc = yaml.safe_load(raw)["proof_search_map_audit"]
        consts, design, calls, selfchecks, funcs = stage0_ast(doc["stage0_code"])
        spec = yaml.safe_load(open(SPEC[v], "rb").read())["experiment"]
        hyp = yaml.safe_load(open(HYP[v], "rb").read())["hypothesis"]
        data[v] = {
            "sheet_sha256": hashlib.sha256(raw).hexdigest(),
            "flat": {**flatten(doc["constants"], "constants", {}),
                     **flatten(doc["design_figures"], "design_figures", {})},
            "stage0_consts": {k: jsonable(x) for k, x in consts.items()},
            "stage0_design": design,
            "stage0_calls": calls,
            "stage0_selfchecks": selfchecks,
            "stage0_funcs": funcs,
            "m4_range_texts": {
                "audit constants.m4_envelope_range": doc["constants"].get("m4_envelope_range"),
                "audit design_figures.m4_envelope.range_log2_B": doc["design_figures"]["m4_envelope"].get("range_log2_B"),
                "audit design_figures.m4_envelope.points": doc["design_figures"]["m4_envelope"].get("points"),
                "stage0 M4_RANGE": jsonable(consts.get("M4_RANGE")),
                "stage0 M4_STEP": consts.get("M4_STEP"),
                "stage0 M4_POINTS": consts.get("M4_POINTS"),
                "spec stages.stage_0.m4_envelope_range": spec["stages"]["stage_0"].get("m4_envelope_range"),
                "hyp test_boundary.parameters.m4_envelope_range": hyp["test_boundary"]["parameters"].get("m4_envelope_range"),
            },
            "constants_delta_ids": ([e["id"] for e in doc["constants_delta"] if isinstance(e, dict) and "id" in e]
                                    if isinstance(doc["constants_delta"], list) else
                                    [e["id"] for grp in doc["constants_delta"].values()
                                     if isinstance(grp, list) for e in grp]),
        }
    out = {"sheets": {v: data[v]["sheet_sha256"] for v in data}}
    # 1. constants + design_figures, leaf by leaf
    f2, f3 = data["v2"]["flat"], data["v3"]["flat"]
    rows, diffs = [], []
    for p in sorted(set(f2) | set(f3)):
        a, b = f2.get(p, "<absent>"), f3.get(p, "<absent>")
        same = a == b
        rows.append({"path": p, "q": qtag(p), "v2": a, "v3": b, "identical": same})
        if not same:
            diffs.append({"path": p, "q": qtag(p), "v2": a, "v3": b})
    out["constants_and_design_figures"] = {"leaves": len(rows), "identical": sum(r["identical"] for r in rows),
                                           "differences": diffs, "table": rows}
    # 2. stage0 DESIGN table
    d2, d3 = data["v2"]["stage0_design"], data["v3"]["stage0_design"]
    dd = flatten(d2, "DESIGN", {}), flatten(d3, "DESIGN", {})
    ddiff = [{"key": k, "v2": dd[0].get(k, "<absent>"), "v3": dd[1].get(k, "<absent>")}
             for k in sorted(set(dd[0]) | set(dd[1])) if dd[0].get(k, "<absent>") != dd[1].get(k, "<absent>")]
    out["stage0_DESIGN"] = {"v2_equals_v3": d2 == d3, "leaves": len(dd[1]), "differences": ddiff}
    # 3. stage0 literal constants
    c2, c3 = data["v2"]["stage0_consts"], data["v3"]["stage0_consts"]
    cdiff = [{"name": k, "v2": c2.get(k, "<absent>"), "v3": c3.get(k, "<absent>")}
             for k in sorted(set(c2) | set(c3)) if c2.get(k, "<absent>") != c3.get(k, "<absent>")]
    out["stage0_literal_constants"] = {"v2": c2, "v3": c3, "differences": cdiff}
    # 4. S0 comparison calls and self-checks
    out["stage0_S0_calls"] = {"v2_count": len(data["v2"]["stage0_calls"]),
                              "v3_count": len(data["v3"]["stage0_calls"]),
                              "identical_multiset": data["v2"]["stage0_calls"] == data["v3"]["stage0_calls"],
                              "only_v2": sorted(set(data["v2"]["stage0_calls"]) - set(data["v3"]["stage0_calls"])),
                              "only_v3": sorted(set(data["v3"]["stage0_calls"]) - set(data["v2"]["stage0_calls"]))}
    out["stage0_self_checks"] = {"v2": data["v2"]["stage0_selfchecks"], "v3": data["v3"]["stage0_selfchecks"],
                                 "identical": data["v2"]["stage0_selfchecks"] == data["v3"]["stage0_selfchecks"]}
    # 5. stage0 functions: identical, changed, added, removed
    fv2, fv3 = data["v2"]["stage0_funcs"], data["v3"]["stage0_funcs"]
    out["stage0_functions"] = {
        "identical": sorted(k for k in fv2 if k in fv3 and fv2[k] == fv3[k]),
        "changed": sorted(k for k in fv2 if k in fv3 and fv2[k] != fv3[k]),
        "added_in_v3": sorted(set(fv3) - set(fv2)), "removed_in_v3": sorted(set(fv2) - set(fv3))}
    out["stage0_function_diffs"] = {
        k: list(difflib.unified_diff(fv2[k].splitlines(), fv3[k].splitlines(), "v2", "v3", lineterm="", n=0))
        for k in out["stage0_functions"]["changed"]}
    # 6. m4 range everywhere
    out["m4_range"] = {"v2": data["v2"]["m4_range_texts"], "v3": data["v3"]["m4_range_texts"],
                       "identical": data["v2"]["m4_range_texts"] == data["v3"]["m4_range_texts"]}
    out["constants_delta_ids"] = {v: data[v]["constants_delta_ids"] for v in data}
    json.dump(out, sys.stdout, indent=1, default=str)
    print()


if __name__ == "__main__":
    main()

"""Supplementary D-CARRY check (validator's own code): multiset of decimal
numbers in hypothesis statement (B) and (C) and in the specification's
memory_beside_time rows, version 2 against version 3. PyYAML 6.0.1."""
import json, re, sys, yaml
from collections import Counter
S = sys.argv[1]
num = re.compile(r"-?\d+\.\d+")
res = {}
for part in ("B", "C"):
    seg = {}
    for v in ("v2", "v3"):
        st = yaml.safe_load(open(f"{S}/{v}/hyp.yaml","rb"))["hypothesis"]["statement"]
        m = re.search(r"\(" + part + r"\)(.*?)(\((?:" + chr(ord(part)+1) + r")\)|$)", st, re.S)
        seg[v] = Counter(num.findall(m.group(1)))
    res["hyp_statement_" + part] = {"only_v2": sorted((seg["v2"] - seg["v3"]).elements()),
                                    "only_v3": sorted((seg["v3"] - seg["v2"]).elements())}
for v in ("v2", "v3"):
    pass
rows = {}
for v in ("v2", "v3"):
    e = yaml.safe_load(open(f"{S}/{v}/spec.yaml","rb"))["experiment"]
    rows[v] = e["memory_beside_time"]["rows"]
res["spec_memory_rows_identical"] = rows["v2"] == rows["v3"]
json.dump(res, sys.stdout, indent=1); print()

